import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"让 YAML 变得像它看起来一样简单 | LCTT x X-CMD","titleTemplate":false,"description":"让 YAML 变得像它看起来一样简单 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"让 YAML 变得像它看起来一样简单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"让 YAML 变得像它看起来一样简单 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210930 Make YAML as easy as it looks","title":"让 YAML 变得像它看起来一样简单","tag":"202110","desc":""},"relativePath":"202110/20210930 Make YAML as easy as it looks.md","filePath":"[post].md"}'),h={name:"202110/20210930 Make YAML as easy as it looks.md"};function u(k,s,g,b,A,M){const n=o("Link");return r(),d("div",null,[s[23]||(s[23]=l(`<h1 id="让-yaml-变得像它看起来一样简单" tabindex="-1">让 YAML 变得像它看起来一样简单 <a class="header-anchor" href="#让-yaml-变得像它看起来一样简单" aria-label="Permalink to “让 YAML 变得像它看起来一样简单”">​</a></h1><blockquote><p>YAML 看起来很简单，为什么它这么难写呢？了解成功使用 YAML 的两个秘诀。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/02/101824shamurmpvldpu29a.jpg" alt=""></p><p>如果你曾经尝试过写 YAML，你可能一开始会对它看起来很容易感到高兴。乍一看，经常用于配置文件、Ansible 剧本和普通文件数据库的 YAML 看起来就像购物清单一样直观。然而，YAML 的结构中有很多细微的差别，它隐藏着一个危险的秘密：YAML 实际上是一种高度精确、结构化和令人惊讶的严格语言。好消息是，你只需要了解两件事就可以知道 YAML 的工作原理。</p><p>关于 YAML 的真相是，YAML 中只有两种数据结构：<ruby>序列<rt>sequence</rt></ruby>和<ruby>映射<rt>mapping</rt></ruby>。这是两个花哨的名字，你会发现它代表了你非常熟悉的概念。这篇文章解释了这两种结构，更重要的是，介绍了它们是如何协同工作，使 YAML 成为表示你所关心的数据的强大方式。</p><h3 id="yaml-序列" tabindex="-1">YAML 序列 <a class="header-anchor" href="#yaml-序列" aria-label="Permalink to “YAML 序列”">​</a></h3><p>YAML 序列是一个列表。在其最简单的形式中，每行有一个项目，每行以破折号和空格开始。</p><p>下面是一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- Linux</span></span>
<span class="line"><span>- BSD</span></span>
<span class="line"><span>- Illumos</span></span></code></pre></div><p>不同的语言有不同的方式来表示这种数据。例如，在 Python 中，同一个列表可以写成 <code>[&#39;Linux&#39;, &#39;BSD&#39;, &#39;Illumos&#39;]</code>。当你在现实生活中写一个列表时，例如在你去买菜之前，你写的可能近似于 YAML 序列。</p><h3 id="yaml-映射" tabindex="-1">YAML 映射 <a class="header-anchor" href="#yaml-映射" aria-label="Permalink to “YAML 映射”">​</a></h3><p>YAML 映射是一个关键术语与该术语的定义相结合。在其他语言中，映射被称为“键值对”或“词典”。</p><p>这里有一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>Kernel: Linux</span></span>
<span class="line"><span>CPU: AMD</span></span>
<span class="line"><span>RAM: &#39;16 GB&#39;</span></span></code></pre></div>`,14)),i("p",null,[s[1]||(s[1]=a("不同的语言有不同的方式来表示这种数据。",-1)),e(n,{href:"https://opensource.com/article/21/3/dictionary-values-python"},{default:p(()=>[...s[0]||(s[0]=[a("在 Python 中",-1)])]),_:1}),s[2]||(s[2]=a("，例如，同样的数据可以写成 ",-1)),s[3]||(s[3]=i("code",null,'{"Kernel": "Linux", "CPU": "AMD", "RAM": "16 GB"}',-1)),s[4]||(s[4]=a("。在现实生活中，你可能会使用这种结构来计划，例如，与朋友的游戏之夜。一个朋友报名带零食，另一个报名带一副牌，另一个报名带一个棋盘游戏，等等。",-1))]),s[24]||(s[24]=l(`<h3 id="组合序列和映射" tabindex="-1">组合序列和映射 <a class="header-anchor" href="#组合序列和映射" aria-label="Permalink to “组合序列和映射”">​</a></h3><p>你现在知道 YAML 的语法了。序列和映射是 YAML 中仅有的两种构件，你想在 YAML 中表示的任何东西都可以放在序列或映射中。</p><p>或者同时使用这二者！</p><p>是的，序列和映射可以被组合和嵌套，这就是 YAML 看起来很直观，但同时又感觉很复杂的原因之一。不过，只有四种可能的组合，一旦你学会如何看它们，YAML 就会觉得像它看起来一样简单。</p><h3 id="序列的映射" tabindex="-1">序列的映射 <a class="header-anchor" href="#序列的映射" aria-label="Permalink to “序列的映射”">​</a></h3><p>当你想让一个键项有许多值时，你可以使用一个序列的映射。也就是说，你从一个映射（键）开始，但是给值一个列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>Linux:</span></span>
<span class="line"><span>  - Fedora</span></span>
<span class="line"><span>  - Slackware</span></span>
<span class="line"><span>BSD:</span></span>
<span class="line"><span>  - FreeBSD</span></span>
<span class="line"><span>  - NetBSD</span></span></code></pre></div><p>在这个示例代码中，<code>Linux</code> 是第一个键，它的值是一个序列，其中包含 <code>Fedora</code> 和 <code>Slackware</code>。第二个键是 <code>BSD</code>，它的值是一个序列，包含 <code>FreeBSD</code> 和 <code>NetBSD</code>。</p><h3 id="映射的映射" tabindex="-1">映射的映射 <a class="header-anchor" href="#映射的映射" aria-label="Permalink to “映射的映射”">​</a></h3><p>当你想让一个键项的值中既有键又有值时，你可以使用映射的映射。也就是说，你从一个映射（键）开始，但是给值另一个映射。</p><p>这可能有点欺骗性，但它揭示了 YAML 中使用特定术语的原因：因为你只不过是创建了一个映射的列表，并不意味着你创建了一个序列。这里是一个映射的映射：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>Desktop:</span></span>
<span class="line"><span>  CPU: RISC-V</span></span>
<span class="line"><span>  RAM: &#39;32 GB&#39;</span></span>
<span class="line"><span>Laptop:</span></span>
<span class="line"><span>  CPU: AMD</span></span>
<span class="line"><span>  RAM: &#39;16 GB&#39;</span></span></code></pre></div><p>对大多数人来说，这看起来像一个列表。而且从技术上讲，它是一个列表。但重要的是要认识到，它不是 YAML 序列。它是一个映射，其中包含映射。作为半个 YAML 专家，你可以从明显缺少破折号的地方看出区别。</p><p>在 Ansible 剧本的所有结构中，我发现这个结构最容易欺骗人。作为人类，我们喜欢列表，当我们看到一个数据结构 <em>在字面上</em> 是列表时，大多数人会把它当成 YAML 序列。但是在 YAML 中，虽然序列是列表，但是列表并不总是序列。</p><h3 id="序列的序列" tabindex="-1">序列的序列 <a class="header-anchor" href="#序列的序列" aria-label="Permalink to “序列的序列”">​</a></h3><p>就像你可以嵌套映射一样，你可以将一个序列嵌套到一个序列中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- [Linux, FreeBSD, Illumos]</span></span>
<span class="line"><span>- [YAML, XML, JSON]</span></span></code></pre></div><p>这可能是我在 YAML 的实际使用中遇到的最不常见的数据结构，但有时你需要一个列表的列表。</p><h3 id="映射的序列" tabindex="-1">映射的序列 <a class="header-anchor" href="#映射的序列" aria-label="Permalink to “映射的序列”">​</a></h3><p>你也可以创建一个包含映射的序列。对于人类排序数据的方式来说，这并不太常见，但对于计算机来说，这可能是一个重要的结构。</p><p>这里有一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>-</span></span>
<span class="line"><span>  CPU: AMD</span></span>
<span class="line"><span>  RAM: &#39;16 GB&#39;</span></span>
<span class="line"><span>-</span></span>
<span class="line"><span>  CPU: Intel</span></span>
<span class="line"><span>  RAM: &#39;16 GB&#39;</span></span></code></pre></div><p>对于 YAML，这可能是最不直观的语法。我发现它在 Python 中呈现时更清晰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[{&quot;CPU&quot;: &quot;AMD&quot;, &quot;RAM&quot;: &quot;16 GB&quot;}, {&quot;CPU&quot;: &quot;Intel&quot;, &quot;RAM&quot;: &quot;16 GB&quot;}]</span></span></code></pre></div><p>方括号代表一个列表结构，这个列表包含两个字典。每个字典都包含键值对。</p><h3 id="构建更好的-yaml" tabindex="-1">构建更好的 YAML <a class="header-anchor" href="#构建更好的-yaml" aria-label="Permalink to “构建更好的 YAML”">​</a></h3><p>现在你知道了 YAML 的两个组成部分，以及它们如何被组合起来以表示复杂的数据结构。问题是：你要用 YAML 构建什么？</p><p>和很多人一样，我也使用 YAML 来编写 Ansible 剧本。我还用它作为一种简单的配置格式、作为 D&amp;D 的角色表、表示项目组织所需的目录结构，等等。只要你能适应序列和映射的概念，你会发现 YAML 是一种很容易编写、阅读和（如果有合适的库）解析的格式。</p>`,28)),i("p",null,[s[6]||(s[6]=a("如果你发现自己经常使用 YAML，请下载我们的 ",-1)),e(n,{href:"https://opensource.com/downloads/yaml-cheat-sheet"},{default:p(()=>[...s[5]||(s[5]=[a("YAML 速查表",-1)])]),_:1}),s[7]||(s[7]=a("，以帮助你直观地了解基本数据结构及其组合，并帮助你记住一些额外的语法约定。通过一点点的练习，你会发现 YAML 真的和它看起来一样简单！",-1))]),s[25]||(s[25]=i("hr",null,null,-1)),i("p",null,[s[9]||(s[9]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/9/yaml-cheat-sheet"},{default:p(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/21/9/yaml-cheat-sheet",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[10]||(s[10]=[a("Seth Kenlon",-1)])]),_:1}),s[15]||(s[15]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[11]||(s[11]=[a("lujun9972",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const f=t(h,[["render",u]]);export{m as __pageData,f as default};
